"""Torch port of the PDM proposal simulation: BatchLQR tracker + kinematic bicycle.

Line-for-line faithful to
``navsim/planning/simulation/planner/pdm_planner/simulation/{batch_lqr,
batch_lqr_utils, batch_kinematic_bicycle, pdm_simulator}.py`` (the numpy
reference), with two deliberate differences:

* the batch dimension is ``windows x proposals`` flattened, so one call
  simulates a whole training batch instead of one window;
* the stopping controller and the LQR branch are both evaluated everywhere
  and merged with ``torch.where`` instead of boolean row assignment -- the
  selected values are identical, the shape is GPU-friendly.

Angle conventions are copied exactly: tracking errors are wrapped with
``atan2(sin, cos)``; the propagated heading uses nuPlan's ``principal_value``
(modulo form).  The two differ at the +/-pi boundary, and the CPU oracle uses
each in exactly these places.
"""

from __future__ import annotations

import math
from dataclasses import dataclass

import torch

from t4_e2e_devkit.planning.simulation.planner.pdm_planner.utils.pdm_enums import StateIndex

# DynamicStateIndex used by the scorer.
_CMD_ACCEL = 0
_CMD_STEERING_RATE = 1
_NUM_COMMANDS = 2

# LateralStateIndex used by the scorer.
_LAT_ERROR = 0
_HEAD_ERROR = 1
_STEER_ANGLE = 2

INITIAL_CURVATURE_PENALTY = 1e-10


@dataclass(frozen=True)
class TorchSimulatorConfig:
    """Parameters of BatchLQRTracker/BatchKinematicBicycleModel, one place."""

    wheel_base: float
    discretization_time: float = 0.1
    tracking_horizon: int = 10
    q_longitudinal: float = 10.0
    r_longitudinal: float = 1.0
    q_lateral: tuple[float, float, float] = (1.0, 10.0, 0.0)
    r_lateral: float = 1.0
    jerk_penalty: float = 1e-4
    curvature_rate_penalty: float = 1e-2
    stopping_proportional_gain: float = 0.5
    stopping_velocity: float = 0.2
    max_steering_angle: float = math.pi / 3
    accel_time_constant: float = 0.2
    steering_angle_time_constant: float = 0.05


def _normalize_angle(angle: torch.Tensor) -> torch.Tensor:
    return torch.atan2(torch.sin(angle), torch.cos(angle))


def _principal_value(angle: torch.Tensor, min_: float = -math.pi) -> torch.Tensor:
    return ((angle - min_) % (2.0 * math.pi)) + min_


def _generate_profile(
    initial_condition: torch.Tensor,  # [N]
    derivatives: torch.Tensor,  # [N, M]
    discretization_time: float,
) -> torch.Tensor:  # [N, M+1]
    cumsum = torch.cumsum(derivatives * discretization_time, dim=-1)
    padded = torch.nn.functional.pad(cumsum, (1, 0))
    return initial_condition[..., None] + padded


def _fit_initial_velocity_and_acceleration_profile(
    xy_displacements: torch.Tensor,  # [N, M, 2]
    heading_profile: torch.Tensor,  # [N, M]
    discretization_time: float,
    jerk_penalty: float,
) -> tuple[torch.Tensor, torch.Tensor]:
    batch_size, num_displacements, _ = xy_displacements.shape
    dtype, device = xy_displacements.dtype, xy_displacements.device

    y = xy_displacements.reshape(batch_size, -1)  # [N, 2M]

    a_column = torch.zeros_like(y)
    a_column[:, 0::2] = torch.cos(heading_profile)
    a_column[:, 1::2] = torch.sin(heading_profile)

    a = (a_column[..., None] * discretization_time**2).expand(
        -1, -1, num_displacements
    ).clone()
    a[..., 0] = a_column * discretization_time

    upper = torch.triu(
        torch.ones(
            (num_displacements, num_displacements), dtype=torch.bool, device=device
        ),
        diagonal=1,
    ).repeat_interleave(2, dim=0)  # [2M, M]
    a = a.masked_fill(upper[None, ...], 0.0)

    # Jerk regularizer, replicated statement-for-statement from the reference
    # _make_banded_difference_matrix: note the second assignment OVERWRITES the
    # overlap of the first (columns 1..rows-1), so the result is NOT a clean
    # difference matrix -- it is -I with a single +1 in the last row.  The
    # CPU oracle solves with exactly this matrix, so this port does too.
    rows = num_displacements - 2
    banded = torch.zeros((rows, rows + 1), dtype=dtype, device=device)
    eye = torch.eye(rows, dtype=dtype, device=device)
    banded[:, 1:] = eye
    banded[:, :-1] = -eye
    regularizer = torch.cat(
        [torch.zeros((rows, 1), dtype=dtype, device=device), banded], dim=1
    )[None, ...].expand(batch_size, -1, -1)

    a_t = a.transpose(1, 2)
    normal = a_t @ a + jerk_penalty * (regularizer.transpose(1, 2) @ regularizer)
    # The reference uses pinv, but the regularized normal matrix is positive
    # definite, where pinv and a direct solve agree to rounding.  Batched
    # ``solve`` matters on CUDA: cusolver's batched SVD only covers matrices
    # up to 32x32, so a batched pinv of 512 40x40 systems degenerates into
    # 512 sequential SVDs (~1 s); the batched solve is milliseconds.
    rhs = torch.einsum("bij,bj->bi", a_t, y)
    x = torch.linalg.solve(normal, rhs)

    return x[:, 0], x[:, 1:]


def _fit_initial_curvature_and_curvature_rate_profile(
    heading_displacements: torch.Tensor,  # [N, M]
    velocity_profile: torch.Tensor,  # [N, M]
    discretization_time: float,
    curvature_rate_penalty: float,
    initial_curvature_penalty: float = INITIAL_CURVATURE_PENALTY,
) -> tuple[torch.Tensor, torch.Tensor]:
    batch_size, dim = heading_displacements.shape
    dtype, device = heading_displacements.dtype, heading_displacements.device

    a = torch.tril(torch.ones((dim, dim), dtype=dtype, device=device))[None, ...]
    a = a.expand(batch_size, -1, -1).clone()
    a[:, :, 0] = velocity_profile * discretization_time
    velocity = velocity_profile * discretization_time**2
    a[:, 1:, 1:] = a[:, 1:, 1:] * velocity[:, 1:, None]

    q = curvature_rate_penalty * torch.eye(dim, dtype=dtype, device=device)
    q[0, 0] = initial_curvature_penalty

    a_t = a.transpose(1, 2)
    # Positive definite by construction (initial_curvature_penalty > 0), so a
    # batched solve replaces the reference's pinv at rounding-level agreement;
    # see the velocity fit above for why pinv is pathological on CUDA here.
    rhs = torch.einsum("bij,bj->bi", a_t, heading_displacements)
    x = torch.linalg.solve(a_t @ a + q, rhs)

    return x[:, 0], x[:, 1:]


def _velocity_curvature_profiles(
    poses: torch.Tensor,  # [N, num_poses, 3]
    config: TorchSimulatorConfig,
) -> tuple[torch.Tensor, torch.Tensor]:
    """Velocity [N, num_poses-1] and curvature [N, num_poses-1] profiles."""

    differences = torch.diff(poses, dim=1)
    xy_displacements = differences[..., :2]
    heading_displacements = _normalize_angle(differences[..., 2])

    initial_velocity, acceleration_profile = (
        _fit_initial_velocity_and_acceleration_profile(
            xy_displacements,
            poses[:, :-1, 2],
            config.discretization_time,
            config.jerk_penalty,
        )
    )
    velocity_profile = _generate_profile(
        initial_velocity, acceleration_profile, config.discretization_time
    )
    initial_curvature, curvature_rate_profile = (
        _fit_initial_curvature_and_curvature_rate_profile(
            heading_displacements,
            velocity_profile,
            config.discretization_time,
            config.curvature_rate_penalty,
        )
    )
    curvature_profile = _generate_profile(
        initial_curvature, curvature_rate_profile, config.discretization_time
    )
    return velocity_profile, curvature_profile


_LATERAL_CONST_CACHE: dict = {}


def _lateral_constants(
    dt: float,
    q_lateral: tuple[float, float, float],
    dtype: torch.dtype,
    device: torch.device,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    """Per-(dt, dtype, device) constants, hoisted out of the rollout loop.

    Creating these inside the loop assigned Python floats into single CUDA
    elements -- an H2D copy per call that also breaks CUDA-graph capture.
    """

    key = (round(dt, 12), q_lateral, dtype, str(device))
    cached = _LATERAL_CONST_CACHE.get(key)
    if cached is None:
        identity = torch.eye(3, dtype=dtype, device=device)
        in_matrix = torch.zeros((3, 1), dtype=dtype, device=device)
        in_matrix[_STEER_ANGLE, 0] = dt
        q = torch.diag(torch.tensor(q_lateral, dtype=dtype, device=device))
        cached = (identity, in_matrix, q)
        _LATERAL_CONST_CACHE[key] = cached
    return cached


def _lateral_lqr(
    initial_lateral_state: torch.Tensor,  # [N, 3]
    velocity_profiles: torch.Tensor,  # [N, H]
    curvature_profiles: torch.Tensor,  # [N, H]
    config: TorchSimulatorConfig,
) -> torch.Tensor:  # [N]
    batch_size, horizon = velocity_profiles.shape
    dtype, device = velocity_profiles.dtype, velocity_profiles.device
    dt = config.discretization_time

    identity, in_matrix, q = _lateral_constants(
        dt, config.q_lateral, dtype, device
    )

    a = identity[None, ...].expand(batch_size, -1, -1)
    b = torch.zeros((batch_size, 3, 1), dtype=dtype, device=device)
    g = torch.zeros((batch_size, 3), dtype=dtype, device=device)

    for step in range(horizon):
        v = velocity_profiles[:, step]
        step_matrix = identity[None, ...].expand(batch_size, -1, -1).clone()
        step_matrix[:, _LAT_ERROR, _HEAD_ERROR] = v * dt
        step_matrix[:, _HEAD_ERROR, _STEER_ANGLE] = v * dt / config.wheel_base
        affine = torch.zeros((batch_size, 3), dtype=dtype, device=device)
        affine[:, _HEAD_ERROR] = -v * curvature_profiles[:, step] * dt

        a = step_matrix @ a
        b = step_matrix @ b + in_matrix
        g = torch.einsum("bij,bj->bi", step_matrix, g) + affine

    state_error = torch.einsum("bij,bj->bi", a, initial_lateral_state) + g
    # HEAD_ERROR and STEER_ANGLE are adjacent; a slice avoids the CPU index
    # tensor that tuple indexing creates (an H2D copy per call, and a
    # CUDA-graph capture breaker).
    state_error = state_error.clone()
    state_error[:, _HEAD_ERROR : _STEER_ANGLE + 1] = _normalize_angle(
        state_error[:, _HEAD_ERROR : _STEER_ANGLE + 1]
    )

    bt_q = b.transpose(1, 2) @ q  # [N, 1, 3]
    inverse = -1.0 / (
        torch.einsum("bij,bji->bi", bt_q, b) + config.r_lateral
    )  # [N, 1]
    tail = torch.einsum("bij,bj->bi", bt_q, state_error)  # [N, 1]
    return (inverse * tail).squeeze(-1)


def _track_trajectory(
    iteration_index: int,
    current_states: torch.Tensor,  # [N, 11]
    proposal_states: torch.Tensor,  # [N, T+1, 11]
    velocity_profile: torch.Tensor,  # [N, T]
    curvature_profile: torch.Tensor,  # [N, T]
    config: TorchSimulatorConfig,
) -> torch.Tensor:  # [N, 2] commands
    reference = proposal_states[:, iteration_index]

    x_errors = current_states[:, StateIndex.X] - reference[:, StateIndex.X]
    y_errors = current_states[:, StateIndex.Y] - reference[:, StateIndex.Y]
    heading_references = reference[:, StateIndex.HEADING]
    lateral_errors = -x_errors * torch.sin(heading_references) + y_errors * torch.cos(
        heading_references
    )
    heading_errors = _normalize_angle(
        current_states[:, StateIndex.HEADING] - heading_references
    )
    initial_velocity = current_states[:, StateIndex.VELOCITY_X]
    initial_lateral_state = torch.stack(
        [lateral_errors, heading_errors, current_states[:, StateIndex.STEERING_ANGLE]],
        dim=-1,
    )

    num_profile_poses = velocity_profile.shape[1]
    horizon = config.tracking_horizon
    reference_index = min(iteration_index + horizon, num_profile_poses - 1)
    reference_velocities = velocity_profile[:, reference_index]

    reference_length = reference_index - iteration_index
    batch_size = proposal_states.shape[0]
    reference_curvatures = torch.zeros(
        (batch_size, horizon),
        dtype=proposal_states.dtype,
        device=proposal_states.device,
    )
    reference_curvatures[:, :reference_length] = curvature_profile[
        :, iteration_index:reference_index
    ]
    if reference_length < horizon:
        reference_curvatures[:, reference_length:] = curvature_profile[
            :, reference_index, None
        ]

    # Stopping P controller (evaluated everywhere, selected by mask below).
    should_stop = (reference_velocities <= config.stopping_velocity) & (
        initial_velocity <= config.stopping_velocity
    )
    stopping_accel = -config.stopping_proportional_gain * (
        initial_velocity - reference_velocities
    )

    # Longitudinal LQR: A = 1, B = horizon * dt, g = 0, closed form.
    b_long = horizon * config.discretization_time
    error_zero_input = initial_velocity - reference_velocities
    inverse = -1.0 / (
        b_long * config.q_longitudinal * b_long + config.r_longitudinal
    )
    lqr_accel = inverse * b_long * config.q_longitudinal * error_zero_input

    velocity_profiles = _generate_profile(
        initial_velocity,
        lqr_accel[:, None].expand(-1, horizon),
        config.discretization_time,
    )[:, :horizon]
    lqr_steering_rate = _lateral_lqr(
        initial_lateral_state, velocity_profiles, reference_curvatures, config
    )

    accel = torch.where(should_stop, stopping_accel, lqr_accel)
    steering_rate = torch.where(
        should_stop, torch.zeros_like(lqr_steering_rate), lqr_steering_rate
    )

    commands = torch.zeros(
        (batch_size, _NUM_COMMANDS),
        dtype=proposal_states.dtype,
        device=proposal_states.device,
    )
    commands[:, _CMD_ACCEL] = accel
    commands[:, _CMD_STEERING_RATE] = steering_rate
    return commands


def _propagate_state(
    states: torch.Tensor,  # [N, 11]
    commands: torch.Tensor,  # [N, 2]
    config: TorchSimulatorConfig,
) -> torch.Tensor:  # [N, 11]
    dt = config.discretization_time

    accel = states[:, StateIndex.ACCELERATION_X]
    steering_angle = states[:, StateIndex.STEERING_ANGLE]
    ideal_accel_x = commands[:, _CMD_ACCEL]
    ideal_steering_angle = dt * commands[:, _CMD_STEERING_RATE] + steering_angle
    updated_accel_x = (
        dt / (dt + config.accel_time_constant) * (ideal_accel_x - accel) + accel
    )
    updated_steering_angle = (
        dt
        / (dt + config.steering_angle_time_constant)
        * (ideal_steering_angle - steering_angle)
        + steering_angle
    )
    updated_steering_rate = (updated_steering_angle - steering_angle) / dt

    # get_state_dot on the command-filtered state.
    longitudinal_speed = states[:, StateIndex.VELOCITY_X]
    heading = states[:, StateIndex.HEADING]
    x_dot = longitudinal_speed * torch.cos(heading)
    y_dot = longitudinal_speed * torch.sin(heading)
    heading_dot = (
        longitudinal_speed * torch.tan(steering_angle) / config.wheel_base
    )

    output = states.clone()
    output[:, StateIndex.X] = states[:, StateIndex.X] + x_dot * dt
    output[:, StateIndex.Y] = states[:, StateIndex.Y] + y_dot * dt
    output[:, StateIndex.HEADING] = _principal_value(heading + heading_dot * dt)
    output[:, StateIndex.VELOCITY_X] = longitudinal_speed + updated_accel_x * dt
    output[:, StateIndex.VELOCITY_Y] = 0.0
    # The reference integrates from the *unfiltered* steering angle with the
    # filtered rate (propagating_state keeps the original angle), which lands
    # exactly on updated_steering_angle -- written in that form here too.
    output[:, StateIndex.STEERING_ANGLE] = torch.clamp(
        steering_angle + updated_steering_rate * dt,
        -config.max_steering_angle,
        config.max_steering_angle,
    )
    output[:, StateIndex.ANGULAR_VELOCITY] = (
        output[:, StateIndex.VELOCITY_X]
        * torch.tan(output[:, StateIndex.STEERING_ANGLE])
        / config.wheel_base
    )
    output[:, StateIndex.ACCELERATION_X] = updated_accel_x
    output[:, StateIndex.ACCELERATION_Y] = 0.0
    output[:, StateIndex.ANGULAR_ACCELERATION] = (
        output[:, StateIndex.ANGULAR_VELOCITY] - states[:, StateIndex.ANGULAR_VELOCITY]
    ) / dt
    output[:, StateIndex.STEERING_RATE] = updated_steering_rate
    return output


def _rollout(
    proposal_states: torch.Tensor,  # [N, T+1, 11]
    initial_states: torch.Tensor,  # [N, 11]
    velocity_profile: torch.Tensor,  # [N, T]
    curvature_profile: torch.Tensor,  # [N, T]
    config: TorchSimulatorConfig,
) -> torch.Tensor:
    """The sequential 40-step tracker+bicycle loop, profiles precomputed.

    Kept free of pinv/SVD so it is CUDA-graph capturable: the whole loop is
    ~4400 tiny kernels whose launch overhead dominates eager execution.
    """

    num_steps = proposal_states.shape[1] - 1
    simulated = [initial_states]
    for time_index in range(1, num_steps + 1):
        commands = _track_trajectory(
            time_index - 1,
            simulated[-1],
            proposal_states,
            velocity_profile,
            curvature_profile,
            config,
        )
        simulated.append(_propagate_state(simulated[-1], commands, config))
    return torch.stack(simulated, dim=1)


_ROLLOUT_CACHE: dict = {}


def _rollout_maybe_compiled(config_key, *args):
    """Replay the rollout as a manually captured CUDA graph.

    The 40-step loop is ~8k tiny kernels whose launch overhead dominates
    (~1 s eager); one capture per (shape, dtype, device) collapses it to a
    single ~16 ms replay that is bit-identical to eager execution.  Static
    input buffers are refreshed with ``copy_`` before each replay; the
    returned tensor is the graph's static output and is only valid until the
    next replay of the same graph -- the scoring stage consumes it before the
    next batch arrives.
    """

    proposal_states = args[0]
    if not proposal_states.is_cuda:
        return _rollout(*args)
    config = args[-1]
    tensors = args[:-1]
    key = (
        config_key,
        tuple(t.shape for t in tensors),
        proposal_states.dtype,
        proposal_states.device.index,
    )
    entry = _ROLLOUT_CACHE.get(key)
    if entry is None:
        static_inputs = [t.clone() for t in tensors]
        stream = torch.cuda.Stream(device=proposal_states.device)
        stream.wait_stream(torch.cuda.current_stream())
        with torch.cuda.stream(stream):
            for _ in range(3):
                _rollout(*static_inputs, config)
        torch.cuda.current_stream().wait_stream(stream)
        graph = torch.cuda.CUDAGraph()
        # Two capture settings make this safe inside a live DDP trainer:
        # ``stream=stream`` captures on the very stream the warmup ran on, so
        # the cuBLAS workspace for that stream already exists and no
        # allocation happens mid-capture; ``thread_local`` scopes the
        # capture-legality check to this thread, tolerating the DataLoader
        # pin-memory threads and the NCCL watchdog allocating concurrently
        # (default "global" mode invalidates the capture when they do).
        with torch.cuda.graph(
            graph, stream=stream, capture_error_mode="thread_local"
        ):
            static_output = _rollout(*static_inputs, config)
        entry = (graph, static_inputs, static_output)
        _ROLLOUT_CACHE[key] = entry
    graph, static_inputs, static_output = entry
    for static, value in zip(static_inputs, tensors):
        static.copy_(value)
    graph.replay()
    return static_output


def simulate_proposals_torch(
    proposal_states: torch.Tensor,  # [N, T+1, 11]
    initial_states: torch.Tensor,  # [N, 11]
    config: TorchSimulatorConfig,
    compile_rollout: bool = False,
) -> torch.Tensor:  # [N, T+1, 11]
    """The PDMSimulator loop over tensors; N may span many windows."""

    num_steps = proposal_states.shape[1] - 1
    velocity_profile, curvature_profile = _velocity_curvature_profiles(
        proposal_states[..., :3], config
    )
    if compile_rollout:
        return _rollout_maybe_compiled(
            (config.wheel_base, config.discretization_time),
            proposal_states,
            initial_states,
            velocity_profile,
            curvature_profile,
            config,
        )
    return _rollout(
        proposal_states, initial_states, velocity_profile, curvature_profile, config
    )
